//! Canonical OptGroup interface over actual native and inert HTML records.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><select id=select><optgroup id=optgroup label=Group><option value=one>One</option></optgroup></select><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://optgroup-interface.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]fn optgroup_interface_canonical_constructor_prototype_and_no_construction(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var C=HTMLOptGroupElement,P=C.prototype,x=document.getElementById('optgroup'),g=Object.getOwnPropertyDescriptor(window,'HTMLOptGroupElement'),tag=Object.getOwnPropertyDescriptor(P,Symbol.toStringTag);if(!(x instanceof C)||!(x instanceof HTMLElement)||Object.getPrototypeOf(x)!==P||Object.getPrototypeOf(P)!==HTMLElement.prototype||Object.getPrototypeOf(C)!==HTMLElement||P.constructor!==C||C.name!=='HTMLOptGroupElement'||C.length!==0||g.value!==C||g.enumerable||!g.writable||!g.configurable||tag.value!=='HTMLOptGroupElement'||tag.writable||tag.enumerable||!tag.configurable)throw 'canonical OptGroup';for(var mode of [0,1,2]){var caught=false;try{if(mode===0)C();else if(mode===1)new C();else new (C.bind(null))();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal OptGroup constructor';}
"#);}
#[test]fn optgroup_interface_exact_factories_namespaces_and_inherited_actual_attributes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),P=HTMLOptGroupElement.prototype;for(var x of [document.getElementById('optgroup'),document.createElement('OPTGROUP'),owner.createElementNS('http://www.w3.org/1999/xhtml','t:optgroup')]){if(!(x instanceof HTMLOptGroupElement)||Object.getPrototypeOf(x)!==P||x.localName!=='optgroup')throw 'actual OptGroup factory';x.id='A\udfffZ';var attr=x.getAttributeNode('id');if(x.id!=='A\udfffZ'||attr.ownerElement!==x||attr.value!==x.id||Object.hasOwn(x,'id'))throw 'inherited exact OptGroup attributes';}for(var wrong of [document.createElementNS('urn:foreign','optgroup'),owner.createElementNS('http://www.w3.org/1999/xhtml','OPTGROUP'),document.createElement('div'),document.createElement('x-optgroup')])if(wrong instanceof HTMLOptGroupElement)throw 'exact OptGroup interface boundary';
"#);}
#[test]fn optgroup_interface_child_owner_and_saved_identity_after_global_deletion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var C=HTMLOptGroupElement,P=C.prototype,x=document.getElementById('optgroup'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow.HTMLOptGroupElement;if(child===C||child.prototype.constructor!==child||Object.getPrototypeOf(child.prototype)!==frame.contentWindow.HTMLElement.prototype)throw 'child OptGroup canonical owner';delete window.HTMLOptGroupElement;if(!(x instanceof C)||Object.getPrototypeOf(document.createElement('optgroup'))!==P||P.constructor!==C)throw 'retained OptGroup authority';
"#);}

#[test]fn optgroup_interface_author_prototype_grants_no_native_element_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'id'),calls=0;for(var bad of [{},Object.create(HTMLOptGroupElement.prototype)]){var caught=false;try{descriptor.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'OptGroup author prototype is not a native Element';}var C=HTMLOptGroupElement,P=C.prototype;P.constructor=17;delete window.HTMLOptGroupElement;if(Object.getPrototypeOf(document.createElement('optgroup'))!==P||P.constructor!==17)throw 'OptGroup prototype mutation cannot replace native identity';");}
#[test]fn optgroup_interface_saved_child_inherited_access_checks_origin_before_hooks(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('optgroup'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var descriptor=Object.getOwnPropertyDescriptor(frame.contentWindow.Element.prototype,'id'),calls=0;");p.set_location(&crate::navigation::address("https://other-optgroup-interface.test/",&crate::navigation::Location::home()).unwrap());let tree=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute("descriptor.set.call(x,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!(p.state.dom_commits,commits);p.set_location(&crate::navigation::address("https://optgroup-interface.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'OptGroup origin before hooks';descriptor.set.call(x,'recovered');if(x.id!=='recovered'||!(x instanceof HTMLOptGroupElement))throw 'OptGroup fresh origin recovery';");}
